// Scraped from the live archive at alidemirbas.com.tr/lab/crm-journeys
import type { CommunicationClass } from "@/lib/orchestration";

export type FlowStep = {
  t: string;
  a: string;
  b: string;
  /** Title shown on the action card's scan-mode front face - a short summary
      of `b`, not present for wait/condition/entry/exit steps. */
  title?: string;
  /** 1-indexed column when this step is part of a parallel branch run -
      consecutive steps sharing different branch numbers render as side-by-
      side paths; the run ends at the first following step with no branch
      field, which becomes the merge point (or the journey just ends if the
      branch is the last thing in the array - a separate, non-merging exit
      per branch). */
  branch?: number;
  /** Caption shown above a branch column's first card, e.g. "HIGH-VALUE
      TIER" - set on that column's first step only. */
  branchLabel?: string;
  /** Overrides the journey's own `communicationClass` for THIS step only -
      only set where a journey genuinely mixes classes (see canSend() in
      orchestration.ts). Absent on every step of a journey that doesn't. */
  commClass?: CommunicationClass;
};
